-- =============================================================
--  Sudoku – CHỐNG GIAN LẬN (chạy SAU schema.sql)
--  Supabase → SQL Editor → dán toàn bộ → Run. Chạy lại nhiều lần không sao.
--
--  Cách hoạt động:
--  1. Đề + lời giải 240 màn nằm trong schema "private" (app không đọc được).
--  2. Bắt đầu màn → start_level() cấp "vé" (token) và ghi giờ bắt đầu trên máy chủ.
--  3. Thắng → submit_solution() gửi vé + bàn cờ đã giải. Máy chủ kiểm tra
--     bàn cờ khớp lời giải và TỰ TÍNH thời gian = lúc nộp − lúc cấp vé.
--  4. Thời gian nhanh hơn mức tối thiểu chạm màn hình (0,5 giây/ô trống) bị từ chối.
--  5. Hàm submit_score cũ (cho tự khai thời gian) bị xóa.
-- =============================================================

create schema if not exists private;
revoke all on schema private from public, anon, authenticated;

create table if not exists private.levels (
  level_id text primary key,
  puzzle   char(81) not null,
  solution char(81) not null
);

-- Đề cố định – PHẢI giống hệt assets/levels.json trong app
on conflict (level_id) do update
  set puzzle = excluded.puzzle, solution = excluded.solution;

-- Phiên chơi (vé)
create table if not exists private.level_sessions (
  token      uuid primary key default gen_random_uuid(),
  player_id  uuid not null,
  level_id   text not null references private.levels (level_id),
  started_at timestamptz not null default now(),
  used_at    timestamptz
);
create index if not exists level_sessions_player_idx
  on private.level_sessions (player_id, level_id);

-- ---------- Bắt đầu màn: cấp vé ----------
create or replace function public.start_level(p_level_id text)
returns uuid
language plpgsql
security definer
set search_path = public, private
as $$
declare
  uid uuid := auth.uid();
  tok uuid;
begin
  if uid is null then
    raise exception 'Chưa đăng nhập';
  end if;
  if not exists (select 1 from private.levels where level_id = p_level_id) then
    raise exception 'Màn không tồn tại';
  end if;
  -- Mỗi người chỉ giữ 1 vé đang mở cho mỗi màn; dọn vé quá 2 ngày
  delete from private.level_sessions
   where player_id = uid
     and (level_id = p_level_id or started_at < now() - interval '2 days');
  values (uid, p_level_id)
  returning token into tok;
  return tok;
end;
$$;

-- ---------- Nộp lời giải: máy chủ kiểm tra + tính giờ ----------
create or replace function public.submit_solution(
  p_token    uuid,
  p_board    text,
  p_mistakes integer,
  p_hints    integer
) returns table (best integer, time_seconds integer)
language plpgsql
security definer
set search_path = public, private
as $$
declare
  uid uuid := auth.uid();
  s   private.level_sessions%rowtype;
  lv  private.levels%rowtype;
  t   integer;
  min_t integer;
begin
  if uid is null then
    raise exception 'Chưa đăng nhập';
  end if;

  select * into s from private.level_sessions
   where token = p_token and player_id = uid
   for update;
  if not found then
    raise exception 'Vé không hợp lệ';
  end if;
  if s.used_at is not null then
    raise exception 'Vé đã được dùng';
  end if;
  if s.started_at < now() - interval '24 hours' then
    raise exception 'Vé đã hết hạn';
  end if;

  select * into lv from private.levels where level_id = s.level_id;
  if p_board is null or p_board !~ '^[1-9]{81}$' or p_board <> lv.solution then
    raise exception 'Lời giải không đúng';
  end if;
  if p_hints is null or p_hints < 0 or p_hints > 3 then
    raise exception 'Số gợi ý không hợp lệ';
  end if;

  t := ceil(extract(epoch from now() - s.started_at))::integer;
  -- Tối thiểu 0,5 giây cho mỗi ô trống (giới hạn tốc độ chạm màn hình)
  min_t := greatest(10, ceil((81 - length(replace(lv.puzzle, '0', ''))) * 0.5))::integer;
  if t < min_t then
    raise exception 'Thời gian không hợp lệ';
  end if;

  update private.level_sessions set used_at = now() where token = p_token;

  values (uid, s.level_id, t, greatest(0, least(coalesce(p_mistakes, 0), 100)), p_hints)
  on conflict (player_id, level_id) do update
    set time_seconds = excluded.time_seconds,
        mistakes     = excluded.mistakes,
        hints        = excluded.hints,
        updated_at   = now()
    where excluded.time_seconds < public.level_scores.time_seconds;

  return query
    select ls.time_seconds, t
    from public.level_scores ls
    where ls.player_id = uid and ls.level_id = s.level_id;
end;
$$;

revoke all on function public.start_level(text) from public, anon;
grant execute on function public.start_level(text) to authenticated;
revoke all on function public.submit_solution(uuid, text, integer, integer) from public, anon;
grant execute on function public.submit_solution(uuid, text, integer, integer) to authenticated;

-- Xóa đường gửi điểm cũ (cho phép tự khai thời gian)
drop function if exists public.submit_score(text, integer, integer, integer);
